import { DAY, DEFAULT_RATES, dateMs, iso, dates, season, energyValue, deviceEnergy, validateDevice, solarIntervals, solarSummary, validateState, seedState, num, eventValue, usageSummary, roomKey, nextRoomColor, updateRoom, removeRoom, roomUsage, sortByLocationGridCost, reportingPeriod, periodItems, nightSchedule, mergeIdleActive } from './energy.js'

const $ = (s, root=document) => root.querySelector(s)
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))
const money = n => new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n)
const fmt = (n,p=1) => new Intl.NumberFormat('en-US',{maximumFractionDigits:p}).format(n)
const dateLabel = (s,year=false) => new Date(dateMs(s)).toLocaleDateString('en-US',{month:'short',day:'numeric',...(year?{year:'numeric'}:{}),timeZone:'UTC'})
const today = () => new Intl.DateTimeFormat('en-CA',{timeZone:'America/Denver',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())
const uid = () => crypto.randomUUID()
const paths = {
  overview:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
  solarPanel:'<path d="M5 10h14l3 10H2l3-10Zm7 0v10M4 15h16m-8 5v3m-4 0h8"/><circle cx="12" cy="4" r="2"/><path d="M12 0v1M5 4h2m10 0h2M7 0l1 1m9-1-1 1"/>',
  devices:'<path d="M8 3v5m8-5v5M6 8h12v3a6 6 0 0 1-12 0V8Zm6 9v5"/>',
  solar:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',
  bills:'<path d="M6 3h12v19l-3-2-3 2-3-2-3 2V3Zm3 5h6m-6 4h6m-6 4h3"/>',
  rates:'<path d="m4 18 5-5 4 3 7-11M15 5h5v5"/>',
  plus:'<path d="M12 5v14M5 12h14"/>',
  calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18"/>',
  info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',
  arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
  grid:'<path d="m8 2-4 20m12-20 4 20M7 6h10M6 11h12M5 16h14M12 2v20"/>',
  export:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',
}
const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.devices}</svg>`
const titles={devices:'Devices',bills:'Utility bills',rates:'Rates & time of use'}
const PUBLISHED_STATE=null
const READ_ONLY=PUBLISHED_STATE!==null
let state, storageOK=true, loadWarning=''
try { const saved=READ_ONLY?null:localStorage.getItem('housecurrent-v1');state=READ_ONLY?validateState(structuredClone(PUBLISHED_STATE)):saved?validateState(JSON.parse(saved)):seedState() }
catch(e){state=seedState();storageOK=false;loadWarning='Stored data could not be loaded. Restore an exported backup, or export the current state before making changes. '+e.message}
let periodChoice='current'
try{periodChoice=localStorage.getItem('housecurrent-period-v1')||'current'}catch{}
let period=reportingPeriod(state.bills,today(),periodChoice)
function selectPeriod(choice){period=reportingPeriod(state.bills,today(),choice);periodChoice=period.id;try{localStorage.setItem('housecurrent-period-v1',periodChoice)}catch{}}
let view='devices', filter='', toastTimer
function save(){ if(READ_ONLY)throw new Error('This is a read-only snapshot.');validateState(state);try{localStorage.setItem('housecurrent-v1',JSON.stringify(state));storageOK=true}catch{storageOK=false;toast('Browser storage is unavailable. Export a backup before closing.')} }
function toast(text){ $('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500) }
function priceRange(low,high){return Math.abs(high-low)<.005?money(low):`${money(low)}–${money(high)}`}
function periodBill(){return period.id==='current'?undefined:state.bills.find(b=>b.id===period.id)}
function results(){return state.devices.map(d=>({d,...deviceEnergy(d,period.start,period.end,state.rates,state.nightHours)}))}
function summary(){return usageSummary(state,period.start,period.end)}
function heading(eyebrow,title,sub,actions=''){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="heading-actions">${actions}</div></div>`}
function button(label,action,primary=false,id=''){if(READ_ONLY)return '';return `<button class="btn ${primary?'primary':''}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''}>${icon('plus')}${label}</button>`}
function periodBar(){return `<div class="period-bar">${icon('calendar')}<span class="period-label">Viewing</span><select id="period-select" aria-label="Reporting period"><option value="current" ${period.id==='current'?'selected':''}>${period.id==='current'&&!period.anchored?'Today · add a bill to define periods':'Since this billing period start'}</option>${[...state.bills].sort((a,b)=>b.end.localeCompare(a.end)).map(x=>`<option value="${esc(x.id)}" ${period.id===x.id?'selected':''}>${dateLabel(x.start)} – ${dateLabel(x.end,true)} · bill</option>`).join('')}</select><span class="date-pill">${dateLabel(period.start)} → ${dateLabel(period.end,true)}</span><span class="badge">${dates(period.start,period.end).length} DAYS${period.id==='current'?' · THROUGH TODAY':' · BILLING PERIOD'}</span></div>`}

function kpi(label,value,unit,note,type='grid',extra=''){return `<div class="kpi ${extra}"><div class="kpi-top">${label}${icon(type)}</div><div class="kpi-value">${value}<span>${unit}</span></div><small>${note}</small></div>`}
function rateStrip(){const seasons=[...new Set(dates(period.start,period.end).map(season))],s=seasons[0];return '<div class="rate-strip"><strong>'+ (seasons.length>1?'Your interval crosses seasons':s==='summer'?'Summer rates':'Winter rates')+'</strong>'+ (seasons.length>1?'<span>Summer · $'+state.rates.summerOff.toFixed(5)+'–$'+state.rates.summerPeak.toFixed(5)+'/kWh</span><span>Winter · $'+state.rates.winterOff.toFixed(5)+'–$'+state.rates.winterPeak.toFixed(5)+'/kWh</span>':'<span><i class="dot"></i>Peak · $'+state.rates[s+'Peak'].toFixed(5)+'/kWh</span><span><i class="dot off"></i>Off-peak · $'+state.rates[s+'Off'].toFixed(5)+'/kWh</span>')+'<button class="text-button" data-action="go-rates">See rate schedule ↗</button></div>'}
function emptyDevices(compact=false){return compact?`<div class="device-empty"><div class="empty-icon">${icon('devices')}</div><div><h3>Give every kilowatt-hour a home.</h3><p>Add your first appliance, computer, or other device. Start with watts and a schedule, or readings from a plug-in energy meter.</p></div>${button('Add a device','add-device',true)}</div><div class="next-step"><div class="step-card"><span class="step-num">1</span><div><strong>Name the device</strong><p>Keep it specific: office PC, fridge, or space heater.</p></div></div><div class="step-card"><span class="step-num">2</span><div><strong>Tell us how it runs</strong><p>Watts + hours, or a measured kWh interval.</p></div></div><div class="step-card"><span class="step-num">3</span><div><strong>See its energy footprint</strong><p>Separate grid use from solar-powered loads.</p></div></div></div>`:`<div class="no-data"><div class="empty-icon">${icon('devices')}</div><h3>Your household, one device at a time.</h3><p>No devices added yet. You don’t need smart plugs to get started—an average wattage and a usage schedule work too.</p>${button('Add your first device','add-device',true)}</div>`}
function deviceTable(items,compact=false){
  const roomName=x=>{const name=String(x.d.room||'').trim().replace(/\s+/g,' ')||'Unassigned location';return name[0].toUpperCase()+name.slice(1)}
  if(!compact)items=sortByLocationGridCost(items)
  const roomTotals=roomUsage(items),canManage=!compact&&!READ_ONLY
  let previousRoom=''
  return `<div class="table-wrap"><table><thead><tr><th>Device</th><th>Method / source</th><th class="right">Watts</th><th class="right">Energy</th><th class="right">Base energy value</th>${canManage?'<th class="right">Manage</th>':''}</tr></thead><tbody>${items.map(x=>{
    const room=roomName(x),key=room.toLowerCase(),roomColor=state.rooms.find(r=>roomKey(r.name)===key)?.color||'#899480',newRoom=!compact&&key!==previousRoom
    const total=roomTotals.get(roomKey(x.d.room))
    previousRoom=key
    return `${newRoom?`<tr class="location-heading" style="--room-color:${roomColor}"><th colspan="2" scope="rowgroup"><span class="room-dot" style="background:${roomColor}" aria-hidden="true"></span>${esc(room)} <span class="badge gray">${total.count}</span></th><th class="right room-total">${fmt(total.kwh*1000/(dates(period.start,period.end).length*24),1)} W<small>Daily average</small></th><th class="right room-total">${fmt(total.kwh)} kWh<small>${filter?'Shown items':'Total energy'}</small></th><th class="right room-total">${priceRange(total.gridLow,total.gridHigh)}<small>Base grid cost</small>${total.mixedKwh?`<small>${fmt(total.mixedKwh)} kWh unallocated</small>`:''}</th>${canManage?'<th aria-label="Location actions"></th>':''}</tr>`:''}<tr class="${x.d.source==='solar'?'solar-device':''}"><td><div class="icon-cell"><span class="device-icon">${icon(x.d.source==='solar'?'solarPanel':'devices')}</span><div><strong>${esc(x.d.name)}</strong><small>${esc(x.d.room||'Unassigned location')}${x.d.mode==='event'?' · '+dateLabel(x.d.start,true)+' → '+dateLabel(x.d.end,true):''}${x.excluded?' · partial readings excluded':''}</small></div></div></td><td><span class="badge ${x.d.mode==='event'?'one-time':x.measured?'blue':'gray'}">${x.d.mode==='event'?'ONE-TIME':x.measured?'METERED':'ESTIMATED'}</span><small>${x.d.source==='grid'?'Grid powered':x.d.source==='solar'?'Off-grid solar':'Mixed / unallocated'}</small></td><td class="right"><strong>${x.d.watts==null?'—':fmt(x.d.watts,2)+' W'}</strong>${x.d.mode==='schedule'&&x.d.idleWatts?`<small>${fmt(x.d.idleWatts,2)} W standby</small>`:''}</td><td class="right"><strong>${fmt(x.kwh)} kWh</strong></td><td class="right"><strong>${priceRange(x.low,x.high)}</strong></td>${!canManage?'':`<td class="right"><div class="row-actions">${x.measured?`<button class="text-button" data-action="device-history" data-id="${esc(x.d.id)}">Readings</button>`:''}<button class="text-button" data-action="edit-device" data-id="${esc(x.d.id)}">Edit</button><button class="text-button delete-inline" data-action="delete-device" data-id="${esc(x.d.id)}">Remove</button></div></td>`}</tr>`}).join('')}</tbody></table></div>`}
function billContext(){const b=periodBill(),solar=solarSummary(state,period.start,period.end);if(!b&&!solar.intervals.length)return '';return `<section class="bill-context" aria-label="Billing summary"><div><strong>${b?'Utility bill':'Solar meter'}</strong><small>${dateLabel(period.start)} – ${dateLabel(period.end,true)}</small></div>${b?`<div><small>Billed grid electricity</small><strong>${fmt(b.kwh)} kWh</strong></div><div><small>Base energy charges</small><strong>${b.energy==null?'—':money(b.energy)}</strong></div>`:''}${solar.intervals.length?`<div><small>Solar meter output</small><strong>${fmt(solar.measured)} kWh</strong></div>`:''}${b?'<a class="text-button" href="#bills">View bill ↗</a>':''}</section>`}
function devices(){const s=summary(),visible=periodItems(s.items,period.start,period.end),items=visible.filter(x=>(x.d.name+' '+x.d.room).toLowerCase().includes(filter.toLowerCase()));return heading('YOUR ENERGY INVENTORY','Know what’s using the power.',READ_ONLY?'Household devices and energy use.':'Add measured usage or an everyday schedule. Refine it as you learn more.',button('Add device','add-device',true)+button('One-time use','add-event')+button('Locations','rooms'))+periodBar()+billContext()+`<div class="kpis device-kpis">${kpi('Grid energy used',fmt(s.kwh),'kWh','Tracked grid devices + one-time use','grid')}${kpi('Solar energy used',fmt(s.solarKwh),'kWh','Tracked solar devices + one-time use','solar','solar')}${kpi('Average daily grid use',fmt(s.averageKwhPerDay,2),'kWh/day',`Grid energy ÷ ${dates(period.start,period.end).length} days`,'devices','daily-grid')}${kpi('Base grid energy cost',priceRange(s.low,s.high),'','Excludes fixed charges, riders, and tax','bills')}${kpi('Saved from solar',priceRange(s.solarLow,s.solarHigh),'','Estimated avoided base energy · tracked solar loads','solar','solar')}</div><div class="card"><div class="section-row inventory-header"><h2>Device inventory <span class="badge gray">${visible.length}</span></h2><div class="inventory-tools"><input id="device-search" class="inventory-search" type="search" aria-label="Search devices" placeholder="Search devices or locations…" value="${esc(filter)}"></div></div>${state.devices.length?items.length?deviceTable(items):`<div class="no-data">${filter?'No devices match your search.':'No devices or one-time uses in this billing period.'}</div>`:emptyDevices()}</div>${s.items.some(x=>x.excluded)?'<div class="notice warning" style="margin-top:20px">Some measured entries only partly overlap these dates and are excluded. Select a period that includes each full interval.</div>':''}`}
function billDetail(b){return `<article class="card bill-card"><header><div><p class="eyebrow">${esc(b.provider||'Electric utility')} · ELECTRICITY ONLY</p><h2>${dateLabel(b.start)} – ${dateLabel(b.end,true)}</h2><p class="subtitle">${dates(b.start,b.end).length} days · ${b.statement?'Statement '+dateLabel(b.statement,true):'Manual bill entry'}</p></div><div class="row-actions"><button class="text-button" data-action="use-bill" data-id="${esc(b.id)}">View period ↗</button>${READ_ONLY?'':`<button class="text-button" data-action="edit-bill" data-id="${esc(b.id)}">Edit</button><button class="text-button delete-inline" data-action="delete-bill" data-id="${esc(b.id)}">Remove</button>`}</div></header><div class="bill-summary"><div><small>Grid electricity</small><strong>${fmt(b.kwh)} <small style="display:inline">kWh</small></strong></div><div><small>Electricity total</small><strong>${money(b.total)}</strong></div><div><small>On-peak share</small><strong>${b.kwh?fmt(b.peakKwh/b.kwh*100):0}%</strong></div></div>${b.segments?.length?`<div class="table-wrap"><table><thead><tr><th>Energy line item</th><th class="right">kWh</th><th class="right">$/kWh</th><th class="right">Billed charge</th></tr></thead><tbody>${b.segments.map(x=>`<tr><td>${esc(x.label)}</td><td class="right">${fmt(x.kwh,2)}</td><td class="right">${Number(x.rate).toFixed(5)}</td><td class="right">${money(x.charge)}</td></tr>`).join('')}</tbody></table></div>`:''}<div class="charge-row"><span>Base energy charges ${b.energy==null?'(not entered)':''}</span><strong>${b.energy==null?'—':money(b.energy)}</strong></div><div class="charge-row"><span>Other electricity charges, fees & tax</span><strong>${b.energy==null?'—':money(b.total-b.energy)}</strong></div><div class="charge-row total"><span>Total electricity service</span><span>${money(b.total)}</span></div><p class="source-note">${esc(b.note||'Entered manually. Read-to-read dates; the ending read date is excluded from interval calculations.')}</p></article>`}
function billsView(){return heading('THE GROUND TRUTH','Start with the utility meter.','Your actual electricity bills anchor the picture. Device estimates fill in the detail.',button('Add electricity bill','add-bill',true))+`<div class="notice">Your supplied October 16 bill is already entered. It spans summer and winter rates. The $20.45 natural gas service and payment/balance details are excluded. ${READ_ONLY?'':'Future bills can be added manually.'}</div>${[...state.bills].sort((a,b)=>b.end.localeCompare(a.end)).map(billDetail).join('')||'<div class="card no-data">No utility bills yet.</div>'}`}
function ratesView(){const r=state.rates;return heading('THE RULES BEHIND THE NUMBERS','Right time. Different rate.','RE-TOU rates from your supplied schedule, interpreted in household Mountain Time.',READ_ONLY?'':`<button class="btn" data-action="edit-rates">Edit rate settings</button>`)+`<div class="card"><div class="card-header"><div><h2>Seasonal electricity rates</h2><p>Base energy prices per kWh. Fees, riders, adjustments, and taxes are separate.</p></div><span class="badge gold">YOUR SUPPLIED SCHEDULE</span></div><div class="table-wrap"><table class="rate-table"><thead><tr><th>Time period</th><th>SUMMER · JUN 1 – SEP 30</th><th>WINTER · OCT 1 – MAY 31</th></tr></thead><tbody><tr><td><strong><i class="dot"></i>On-peak</strong><small>Monday–Friday, 5 pm–9 pm</small></td><td class="price">$${r.summerPeak.toFixed(5)}<small>/ kWh</small></td><td class="price">$${r.winterPeak.toFixed(5)}<small>/ kWh</small></td></tr><tr><td><strong><i class="dot off"></i>Off-peak</strong><small>All other times, including weekends</small></td><td class="price">$${r.summerOff.toFixed(5)}<small>/ kWh</small></td><td class="price">$${r.winterOff.toFixed(5)}<small>/ kWh</small></td></tr><tr><td><strong>Flat rate (R-OO)</strong><small>Opt-out comparison · all day</small></td><td class="price">$${r.summerFlat.toFixed(5)}<small>/ kWh</small></td><td class="price">$${r.winterFlat.toFixed(5)}<small>/ kWh</small></td></tr></tbody></table></div><p class="source-note">Transcribed from your supplied rate image. No effective date was shown. ${READ_ONLY?'Recorded bill charges remain separate from device estimates.':'Editable for future changes; edits recalculate device and solar estimates, while recorded bill charges remain unchanged.'}</p></div><div class="card night-settings"><div class="section-row"><h2>Nighttime hours</h2>${READ_ONLY?'':'<button class="btn" data-action="edit-night">Edit nighttime hours</button>'}</div><p>Winter · ${esc(state.nightHours.winterStart)}–${esc(state.nightHours.winterEnd)} &nbsp; Summer · ${esc(state.nightHours.summerStart)}–${esc(state.nightHours.summerEnd)}</p><p class="subtitle">Shared by devices with Nighttime hours selected.</p></div><div class="split" style="margin-top:20px"><div class="card"><h2>Your weekly time-of-use window</h2><p class="subtitle">Peak pricing runs from 17:00 up to, but not including, 21:00.</p><div class="schedule-grid"><span></span>${Array.from({length:24},(_,h)=>`<span class="hour">${[0,6,12,18,23].includes(h)?h:''}</span>`).join('')}${['M–F','Sa/Su'].map((label,i)=>`<span>${label}</span>${Array.from({length:24},(_,h)=>`<i class="slot ${!i&&h>=17&&h<21?'peak':''}" aria-hidden="true"></i>`).join('')}`).join('')}</div><div class="rate-key"><span><i class="dot"></i>On-peak</span><span><i class="dot off"></i>Off-peak</span></div></div><div class="card"><h2>Good estimates have clear boundaries.</h2><div class="prose"><p>Device schedules price each hour using its day and season, including runs crossing midnight. A measured interval without timing gets a cost range.</p><p>We apply the weekday rule exactly as supplied. Holiday exceptions and tariff effective-date history are not configured. A single 24-hour wall-clock day is used across daylight-saving transitions.</p></div></div></div>`}
function render(){period=reportingPeriod(state.bills,today(),periodChoice);periodChoice=period.id;const next=location.hash.slice(1);view=titles[next]?next:'devices';if(next!==view)history.replaceState(null,'','#'+view);$('#crumb').textContent=titles[view];document.title=`${titles[view]} · Housecurrent`;document.querySelectorAll('nav a').forEach(a=>{const key=a.dataset.view;a.innerHTML=icon(key)+`<span>${titles[key]}</span>${key==='devices'?`<span>${periodItems(results(),period.start,period.end).length||''}</span>`:''}`;a.classList.toggle('active',key===view);if(key===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');a.setAttribute('aria-label',titles[key])});$('#save-state').textContent=READ_ONLY?'Read-only snapshot':storageOK?'Saved on this device':'Storage issue · export a backup';$('#content').innerHTML=(loadWarning?`<div class="notice warning">${esc(loadWarning)}</div>`:'')+({devices,bills:billsView,rates:ratesView}[view])()}
function modal(title,sub,body,submit='Save',kind='',id=''){ $('#modal-body').innerHTML=`<div class="modal-inner"><div class="modal-top"><div><h2>${title}</h2><p class="subtitle">${sub}</p></div><button class="close-btn" aria-label="Close dialog" data-action="close">×</button></div><form id="active-form" data-kind="${kind}" data-id="${esc(id)}">${body}<div class="form-error" role="alert" id="form-error"></div><div class="form-actions"><button type="button" class="btn" data-action="close">Cancel</button><button class="btn primary" type="submit">${submit}</button></div></form></div>`;$('#modal').setAttribute('aria-label',title);if(!$('#modal').open)$('#modal').showModal() }
function field(label,name,type='text',value='',extra='',hint=''){return `<label class="field">${label}<input type="${type}" name="${name}" value="${esc(value)}" ${extra}>${hint?`<small>${hint}</small>`:''}</label>`}
function select(label,name,options,value){return `<label class="field">${label}<select name="${name}">${options.map(([val,text])=>`<option value="${esc(val)}" ${value===val?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`}
function roomSelect(label,value){return select(label,'room',[['','Unassigned location'],...state.rooms.map(r=>[r.name,r.name])],value)}
function roomsForm(){modal('Locations','Organize your inventory with a distinct color for each location.',`<div class="room-list">${state.rooms.length?state.rooms.map(r=>`<div class="room-item"><span class="room-dot" style="background:${r.color}" aria-hidden="true"></span><strong>${esc(r.name)}</strong><small>${state.devices.filter(d=>roomKey(d.room)===roomKey(r.name)).length} items</small><button type="button" class="text-button" data-action="edit-room" data-id="${esc(r.id)}" aria-label="Edit ${esc(r.name)}">Edit</button><button type="button" class="text-button delete-inline" data-action="remove-room" data-id="${esc(r.id)}" aria-label="Remove ${esc(r.name)}">Remove</button></div>`).join(''):'<p class="subtitle">No locations yet. Devices remain in Unassigned location.</p>'}</div><h3>Add a location</h3><div class="room-editor">${field('Location name','name','text','','required maxlength="80" placeholder="e.g. Living room"')}${field('Location color','color','color',nextRoomColor(state.rooms),'required')}</div><p class="source-note">Each location has a unique color. Removing a location moves its devices to Unassigned location and keeps every reading.</p>`,'Add location','room-add')}
function editRoomForm(id){const r=state.rooms.find(r=>r.id===id);if(!r)throw new Error('Location not found.');modal('Edit location','Renaming updates every device assigned to this location.',`<div class="room-editor">${field('Location name','name','text',r.name,'required maxlength="80"')}${field('Location color','color','color',r.color,'required')}</div>`,'Save location','room-edit',id)}
function removeRoomForm(id){const r=state.rooms.find(r=>r.id===id);if(!r)throw new Error('Location not found.');modal('Remove location?','Device entries and readings will be kept.',`<div class="notice">Remove ${esc(r.name)} from your location list? Its ${state.devices.filter(d=>roomKey(d.room)===roomKey(r.name)).length} assigned items will move to Unassigned location. You can reassign them at any time.</div>`,'Remove location','room-remove',id)}
function formObject(){return Object.fromEntries(new FormData($('#active-form')))}
function toggleBlock(name,html){return `<div data-fields="${name}" class="full">${html}</div>`}
function syncForm(){
 const form=$('#active-form');if(!form)return
 const value=n=>form.elements.namedItem(n)?.value,checked=n=>form.elements.namedItem(n)?.checked
 const night=checked('nightTime'),show={days:value('daysMode')==='specific',run:!night,specific:!night&&value('runMode')!=='always',kwh:value('inputMode')!=='continuous',continuous:value('inputMode')==='continuous'}
 for(const block of form.querySelectorAll('[data-fields]')){const visible=show[block.dataset.fields];block.hidden=!visible;for(const input of block.querySelectorAll('input,select'))input.disabled=!visible}
 // Nested time fields must stay disabled when their enclosing group is hidden.
 for(const input of form.querySelectorAll('[data-fields][hidden] input,[data-fields][hidden] select'))input.disabled=true
}
function deviceForm(d={}){
 const mode=d.mode||'schedule',days=d.days||[0,1,2,3,4,5,6],all=days.length===7
 modal(d.id?'Edit device':'Add a device','Set active power and standby in a single entry.',`<div class="toggle-tabs"><button type="button" class="${mode==='schedule'?'active':''}" data-action="device-mode" data-mode="schedule">Watts + schedule</button><button type="button" class="${mode==='measured'?'active':''}" data-action="device-mode" data-mode="measured">Measured kWh</button></div><input type="hidden" name="mode" value="${mode}"><div class="form-grid">${field('Device name','name','text',d.name||'','required maxlength="100"')}${roomSelect('Location',d.room||'')}<div class="full">${select('Power source','source',[['grid','Grid powered'],['solar','Off-grid solar'],['mixed','Mixed / not allocated']],d.source||'grid')}</div>${mode==='schedule'?`${field('Active power (watts)','watts','number',d.watts??'','required min="0" max="1000000" step="any"')}${field('Idle / standby power (watts)','idleWatts','number',d.idleWatts??0,'min="0" max="1000000" step="any"','Active power is the total while running. Standby applies at other times.')}<label class="night-check full"><input type="checkbox" name="nightTime" ${d.nightTime?'checked':''}> Nighttime hours <small>Uses the shared winter and summer schedule in Rates & time of use.</small></label><div class="full">${select('Days the run starts','daysMode',[['always','Runs every day'],['specific','Runs on specific days']],d.daysMode||(all?'always':'specific'))}</div>${toggleBlock('days',`<div class="days">${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map((x,i)=>`<label><input aria-label="${x}" type="checkbox" name="days" value="${i}" ${days.includes(i)?'checked':''}><span>${x.slice(0,2)}</span></label>`).join('')}</div>`)}${toggleBlock('run',`${select('Hours per run','runMode',[['always','Always running'],['hours','Specific hours per run']],d.runMode||(Number(d.hours)===24?'always':'hours'))}${toggleBlock('specific',`<div class="form-grid">${field('Hours per run','hours','number',d.hours??8,'required min="0.01" max="24" step="any"')}${field('Run starts (Mountain Time)','startTime','time',d.startTime||'09:00','required')}</div><details ${d.summerStartTime&&!d.nightTime?'open':''}><summary>Custom summer schedule (optional)</summary><div class="form-grid">${field('Summer run starts','summerStartTime','time',d.nightTime?'':d.summerStartTime||'')}${field('Summer hours per run','summerHours','number',d.nightTime?'':d.summerHours??'','min="0.01" max="24" step="any"')}</div></details>`)}`)}`:`<div class="full notice">Save the device, then manage its measured intervals using Readings. Existing readings are retained.</div>${field('Power (watts, optional)','watts','number',d.watts??'','min="0" max="1000000" step="any"')}`}${field('Notes (optional)','note','text',d.note||'','maxlength="300"')}</div>`,d.id?'Save device':'Add device','device',d.id||'');syncForm()
}
function eventForm(d={}){
 modal(d.id?'Edit one-time use':'Add one-time use','Record total energy or a continuous draw between two dates.',`<div class="form-grid">${field('Name','name','text',d.name||'','required maxlength="100"')}${roomSelect('Location',d.room||'')}${field('Starting date','start','date',d.start||today(),'required')}${field('Ending date (excluded)','end','date',d.end||iso(dateMs(today())+DAY),'required')}</div>${select('Energy entry','inputMode',[['kwh','Total energy (kWh)'],['continuous','Continuous draw over these dates (watts)']],d.inputMode||'kwh')}${toggleBlock('kwh',`${select('Energy measured at','basis',[['wall','Wall / charging meter — supply energy'],['delivered','Car / equipment — delivered energy']],d.basis||'wall')}<div class="form-grid">${field('Energy (kWh)','kwh','number',d.kwh??'','required min="0" step="any"')}${field('Delivered share (%)','efficiency','number',d.efficiency??90,'required min="0.1" max="100" step="any"','Used only for delivered-energy entries.')}</div>${select('When was this energy used?','timing',[['unknown','Unknown / mixed'],['off','Entirely off-peak'],['peak','Entirely on-peak']],d.timing||'unknown')}<p class="source-note">Total kWh entries must fit completely inside the viewing period.</p>`)}${toggleBlock('continuous',`${field('Continuous power (watts)','watts','number',d.inputMode==='continuous'?d.watts:'','required min="0" max="1000000" step="any"')}<p class="source-note">Runs 24 hours each day. Energy is calculated for the dates that fall inside the viewing period.</p>`)}${select('Power source','source',[['grid','Grid powered'],['solar','Off-grid solar'],['mixed','Mixed / not allocated']],d.source||'grid')}${field('Notes (optional)','note','text',d.note||'','maxlength="500"')}`,'Save one-time use','event',d.id||'');syncForm()
}
function nightForm(){modal('Nighttime hours','Devices with Nighttime hours checked follow these shared settings.',`<div class="form-grid">${field('Winter starts','winterStart','time',state.nightHours.winterStart,'required')}${field('Winter ends','winterEnd','time',state.nightHours.winterEnd,'required')}${field('Summer starts','summerStart','time',state.nightHours.summerStart,'required')}${field('Summer ends','summerEnd','time',state.nightHours.summerEnd,'required')}</div><p class="source-note">Winter: October–May. Summer: June–September. End times earlier than the start are on the following day. Changes recalculate all viewing periods.</p>`,'Save nighttime hours','night-hours')}
function mergeForm(){const options=state.devices.filter(d=>d.mode==='schedule').map(d=>[d.id,`${d.room||'Unassigned'} · ${d.name} (${fmt(d.watts)} W)`]);modal('Merge idle and active entries','Combine two entries for the same equipment, location and power source.',`${field('Combined device name','name','text','','required maxlength="100"')}${select('Continuous idle entry','idleId',options,'')}${select('Active entry','activeId',options,'')}${select('Active reading means','activeMeaning',[['extra','Additional power above the idle entry — preserve current totals'],['total','Total measured power while active']], 'extra')}<p class="source-note">The active schedule is kept. The continuous idle row becomes standby power and is removed. Export a backup before merging.</p>`,'Merge devices','merge')}
function deviceHistory(id){const d=state.devices.find(x=>x.id===id);modal('Device readings',esc(d.name),`<div class="notice">Use the difference between two meter readings, or a resettable meter’s interval total. Intervals must not overlap.</div>${d.logs?.length?`<div class="table-wrap"><table><thead><tr><th>Interval</th><th class="right">kWh</th><th>Manage</th></tr></thead><tbody>${d.logs.map(l=>`<tr><td>${dateLabel(l.start)} – ${dateLabel(l.end,true)}</td><td class="right">${fmt(l.kwh)}</td><td><div class="row-actions"><button type="button" class="text-button" data-action="edit-device-log" data-id="${esc(id)}" data-log="${esc(l.id)}">Edit</button><button type="button" class="text-button delete-inline" data-action="delete-device-log" data-id="${esc(id)}" data-log="${esc(l.id)}">Remove</button></div></td></tr>`).join('')}</tbody></table></div>`:'<p class="subtitle">No measured intervals yet.</p>'}<div style="margin-top:20px"><button type="button" class="btn primary" data-action="add-device-log" data-id="${esc(id)}">+ Add kWh interval</button></div>`,'Done','done')}
function deviceLogForm(id,logId){const d=state.devices.find(x=>x.id===id),log=d.logs?.find(x=>x.id===logId)||{};modal('Log device energy',esc(d.name)+' · Measured kWh for a complete interval.',`<input type="hidden" name="logId" value="${esc(log.id||'')}"><div class="form-grid">${field('Starting read date','start','date',log.start||period.start,'required')}${field('Ending read date (excluded)','end','date',log.end||period.end,'required')}${field('Energy used in interval (kWh)','kwh','number',log.kwh??'','required min="0" step="any"')}${field('On-peak kWh (optional)','peakKwh','number',log.peakKwh??'','min="0" step="any"','Leave blank if timing is unknown.')}</div>`,'Save interval','device-log',id)}
function solarForm(r={}){modal(r.id?'Edit meter reading':'Log a solar meter reading','Use the cumulative energy counter measured from battery output.',`<div class="form-grid">${field('Read date','date','date',r.date||today(),'required')}${field('Cumulative counter (kWh)','kwh','number',r.kwh??'','required min="0" step="any" placeholder="e.g. 142.380"')}</div><p class="source-note">Use kWh, not instantaneous W or battery charge percentage. The first entry is a baseline. Whole-day read-to-read intervals; no time-of-day allocation.</p><label class="field" style="display:block"><input type="checkbox" name="reset" style="width:auto;margin-right:8px" ${r.reset?'checked':''}>New baseline after meter reset / replacement</label>${field('Note (optional)','note','text',r.note||'','maxlength="250" placeholder="e.g. Output meter at battery AC socket"')}`,'Save reading','solar',r.id||'')}
function solarSettings(){modal('Solar meter setup','Make the measurement boundary explicit.',`${field('Meter name','name','text',state.solar.name,'required maxlength="100"')}${select('Where is energy being measured?','kind',[['unknown','Battery output · location not yet confirmed'],['ac','AC power meter after inverter'],['dc','Battery DC/output reading before inverter']],state.solar.kind)}${field('Delivered share if before inverter (%)','efficiency','number',state.solar.efficiency??'','min="0.1" max="100" step="any" placeholder="Optional, e.g. 90"','Optional estimate, not a measured efficiency. Leave blank to report output kWh without a dollar savings estimate. Ignored for an AC meter after the inverter.')}`,'Save setup','solar-settings')}
function billForm(b={}){modal(b.id?'Edit electricity bill':'Add electricity bill','Electricity service only. Exclude gas and account payments.',`<div class="form-grid">${field('Starting meter read','start','date',b.start||period.start,'required')}${field('Ending meter read (excluded)','end','date',b.end||period.end,'required')}${field('Total electricity (kWh)','kwh','number',b.kwh??'','required min="0" step="any"')}${field('On-peak electricity (kWh)','peakKwh','number',b.peakKwh??'','required min="0" step="any"')}${field('Electricity bill total ($)','total','number',b.total??'','required min="0" step="0.01"')}${field('Base energy charges ($, optional)','energy','number',b.energy??'','min="0" step="0.01"')}${field('Statement date (optional)','statement','date',b.statement||'')}${field('Utility name','provider','text',b.provider||'Xcel Energy','maxlength="100"')}</div>${field('Note','note','text',b.note||'','maxlength="400"')}${b.segments?'<p class="source-note">Editing billed totals removes the original line-item detail so it cannot contradict your edits. The exported backup can preserve the original.</p>':''}`,'Save bill','bill',b.id||'')}
function ratesForm(){modal('Edit base energy rates','Changes recalculate estimates, including historical views.',`<div class="notice">Enter dollars per kWh, not cents. The supplied peak schedule stays Monday–Friday, 5–9 pm.</div><div class="form-grid">${Object.entries({summerPeak:'Summer on-peak',summerOff:'Summer off-peak',winterPeak:'Winter on-peak',winterOff:'Winter off-peak',summerFlat:'Summer flat (comparison)',winterFlat:'Winter flat (comparison)'}).map(([key,label])=>field(label+' ($/kWh)',key,'number',state.rates[key],'required min="0" max="10" step="0.00001"')).join('')}</div><div style="margin-top:15px"><button type="button" class="text-button" data-action="default-rates">Reset fields to supplied schedule</button></div>`,'Save rates','rates')}
function explain(){modal('How Housecurrent calculates','A clear boundary between readings and estimates.',`<div class="prose"><h3>Actual bills stay actual.</h3><p>Billed grid kWh is imported electricity, already reduced by any loads powered off-grid. Solar is not subtracted from it again. Your electricity total is separate from base energy charges and from natural gas.</p><h3>Device schedules are estimates.</h3><p>Average watts ÷ 1,000 × hours gives kWh. Continuous standby is counted separately; running watts replace standby during scheduled runs. The schedule is repeated on the selected days and priced by the actual calendar day, season and time. Rates use household Mountain Time, independent of the browser’s timezone. DST transition days use a 24-hour wall-clock model. No holiday exclusions are assumed.</p><h3>Uncertain timing gets a range.</h3><p>Grid measured intervals without a peak split and solar meter journal intervals get a minimum-to-maximum base energy value. Solar-powered device kWh entries instead use estimated averages of $0.08/kWh winter and $0.10/kWh summer; a single interval crossing seasons keeps a range until seasonal kWh are known. We do not invent solar’s hourly profile. Partial intervals are excluded rather than prorated.</p><h3>Solar’s measurement location matters.</h3><p>AC after-inverter kWh is treated as delivered household energy. DC output requires an optional delivered-share estimate; otherwise only measured output is shown. This assumes output serves household loads that would otherwise use grid power. Solar value is not a utility credit.</p>${READ_ONLY?'<h3>Read-only snapshot.</h3><p>Records are included in this website file and load identically across browsers. Updates are made in the local editor, then exported and uploaded as a replacement snapshot. This page has no shared data-writing service.</p>':'<h3>Your data stays in this browser.</h3><p>Device and meter entries are saved in local browser storage; there is no cloud sync. Use Export backup and Restore backup to move data or recover it. Private browsing, clearing site data, or changing browsers can remove access to local records.</p>'}<h3>Reading intervals.</h3><p>Dates are start-inclusive and end-exclusive, matching the 29-day September 15 → October 14 interval on your supplied bill. Record cumulative solar counters at a consistent time; calculations treat them as start-of-day readings.</p></div>`,'Got it','done')}
function confirmRemove(kind,id,logId){const names={device:'device and its readings',solar:'solar reading',bill:'electricity bill','device-log':'device interval'};modal('Remove this '+names[kind]+'?','Export a backup first if you want to keep a copy.',`<div class="notice">${kind==='solar'?'Removing a cumulative reading recomputes the intervals between its neighbours. It does not reset your physical meter.':'This removes only the selected app record. It does not affect any physical meter or utility data.'}</div><input type="hidden" name="targetKind" value="${kind}"><input type="hidden" name="logId" value="${esc(logId||'')}">`,'Remove record','remove',id)}
function exportBackup(){if(READ_ONLY)return;const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`housecurrent-backup-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('Backup downloaded. Keep it somewhere safe.')}
document.addEventListener('click',e=>{const btn=e.target.closest('[data-action]');if(!btn)return;const{action,id,log}=btn.dataset;if(READ_ONLY&&!['close','go-rates','use-bill'].includes(action))return;try{
  if(action==='close')return $('#modal').close()
  if(action==='edit-night')nightForm()
  if(action==='merge-devices')mergeForm()
  if(action==='rooms')roomsForm()
  if(action==='edit-room')editRoomForm(id)
  if(action==='remove-room')removeRoomForm(id)
  if(action==='add-event')eventForm()
  if(action==='add-device')deviceForm()
  if(action==='edit-device'){const d=state.devices.find(d=>d.id===id);if(d.mode==='event')eventForm(d);else deviceForm(d)}
  if(action==='device-mode'){const d=formObject();d.id=$('#active-form').dataset.id;d.days=d.daysMode==='always'?[0,1,2,3,4,5,6]:new FormData($('#active-form')).getAll('days').map(Number);d.nightTime=d.nightTime==='on';d.mode=btn.dataset.mode;deviceForm(d)}
  if(action==='device-history')deviceHistory(id)
  if(action==='add-device-log'||action==='edit-device-log')deviceLogForm(id,log)
  if(action==='delete-device-log')confirmRemove('device-log',id,log)
  if(action==='add-solar')solarForm()
  if(action==='edit-solar')solarForm(state.solarReadings.find(r=>r.id===id))
  if(action==='solar-settings')solarSettings()
  if(action==='add-bill')billForm()
  if(action==='edit-bill')billForm(state.bills.find(b=>b.id===id))
  if(action==='use-bill'){const b=state.bills.find(b=>b.id===id);selectPeriod(b.id);location.hash='devices';render()}
  if(action.startsWith('delete-')&&action!=='delete-device-log')confirmRemove(action.slice(7),id)
  if(action==='go-rates')location.hash='rates'
  if(action==='edit-rates')ratesForm()
  if(action==='default-rates')for(const[key,value]of Object.entries(DEFAULT_RATES))$(`[name="${key}"]`,$('#active-form')).value=value
}catch(error){toast(error.message)}})
document.addEventListener('submit',e=>{if(e.target.id!=='active-form')return;e.preventDefault();if(READ_ONLY){$('#modal').close();return}const form=e.target,f=Object.fromEntries(new FormData(form)),kind=form.dataset.kind,id=form.dataset.id;const oldState=structuredClone(state);try{
  if(kind==='done')return $('#modal').close()
  if(['room-add','room-edit','room-remove'].includes(kind)){
    if(kind==='room-remove')removeRoom(state,id)
    else updateRoom(state,kind==='room-add'?uid():id,f.name,f.color)
    validateState(state);save();render();roomsForm();toast(kind==='room-remove'?'Location removed. Entries kept.':'Location saved.');return
  }
  if(kind==='event'){
    const continuous=f.inputMode==='continuous'
    const d={id:id||uid(),mode:'event',name:f.name.trim(),room:f.room.trim(),source:f.source,start:f.start,end:f.end,inputMode:f.inputMode,basis:continuous?'wall':f.basis,kwh:continuous?0:num(f.kwh,'Energy'),efficiency:continuous?100:num(f.efficiency,'Delivered share',.1,100),timing:continuous?'unknown':f.timing,note:f.note||''}
    if(continuous)d.watts=num(f.watts,'Continuous watts',0,1000000)
    else {const previous=state.devices.find(x=>x.id===id);if(previous?.watts!=null&&previous.inputMode!=='continuous')d.watts=previous.watts}
    validateDevice(d);eventValue(d,state.rates);state.devices=id?state.devices.map(x=>x.id===id?d:x):[...state.devices,d]
  }
  if(kind==='device'){
    const existing=state.devices.find(d=>d.id===id),d={id:id||uid(),name:f.name.trim(),room:f.room.trim(),source:f.source,mode:f.mode,note:f.note||'',logs:existing?.logs||[]}
    if(d.mode==='schedule'){const night=f.nightTime==='on',schedule=night?nightSchedule(state.nightHours,'winter'):f.runMode==='always'?{hours:24,startTime:'00:00'}:{hours:num(f.hours,'Hours',.01,24),startTime:f.startTime};Object.assign(d,{watts:num(f.watts,'Watts'),...schedule,nightTime:night,days:f.daysMode==='always'?[0,1,2,3,4,5,6]:new FormData(form).getAll('days').map(Number)})}
    if(d.mode==='schedule'){
      d.idleWatts=num(f.idleWatts||0,'Idle watts',0,d.watts)
      if(!d.nightTime&&(f.summerStartTime||f.summerHours)){d.summerStartTime=f.summerStartTime;d.summerHours=num(f.summerHours,'Summer hours',.01,24)}
    }
    else {d.logs=existing?.logs||[];if(f.watts!=='')d.watts=num(f.watts,'Watts',0,1000000)}
    validateDevice(d);state.devices=existing?state.devices.map(x=>x.id===id?d:x):[...state.devices,d]
  }
  if(kind==='device-log'){
    const d=state.devices.find(x=>x.id===id),l={id:f.logId||uid(),start:f.start,end:f.end,kwh:num(f.kwh,'kWh'),peakKwh:f.peakKwh===''?null:num(f.peakKwh,'On-peak kWh')}
    dates(l.start,l.end);if(l.peakKwh!=null)energyValue(l.kwh,l.start,l.end,state.rates,l.peakKwh)
    d.logs=f.logId?d.logs.map(x=>x.id===f.logId?l:x):[...(d.logs||[]),l];validateDevice(d)
  }
  if(kind==='solar'){
    const r={id:id||uid(),date:f.date,kwh:num(f.kwh,'Cumulative kWh'),note:f.note||'',reset:f.reset==='on'};dateMs(r.date)
    const readings=id?state.solarReadings.map(x=>x.id===id?r:x):[...state.solarReadings,r];solarIntervals(readings);state.solarReadings=readings
  }
  if(kind==='solar-settings'){state.solar={name:f.name.trim(),kind:f.kind,efficiency:f.efficiency===''?null:num(f.efficiency,'Delivered share',.1,100)}}
  if(kind==='bill'){
    const b={id:id||uid(),start:f.start,end:f.end,kwh:num(f.kwh,'Bill kWh'),peakKwh:num(f.peakKwh,'Peak kWh'),total:num(f.total,'Electricity bill'),energy:f.energy===''?null:num(f.energy,'Base energy charges'),provider:f.provider,statement:f.statement,note:f.note}
    dates(b.start,b.end);if(b.peakKwh>b.kwh)throw new Error('On-peak kWh cannot exceed total kWh.');if(b.energy!=null&&b.energy>b.total)throw new Error('Base energy cannot exceed the electricity total.');if(b.statement)dateMs(b.statement)
    if(state.bills.some(x=>x.id!==id&&x.start===b.start&&x.end===b.end))throw new Error('A bill already exists for those reading dates. Edit it instead.')
    state.bills=id?state.bills.map(x=>x.id===id?b:x):[...state.bills,b];selectPeriod(b.id)
  }
  if(kind==='night-hours'){state.nightHours=Object.fromEntries(['winterStart','winterEnd','summerStart','summerEnd'].map(k=>[k,f[k]]))}
  if(kind==='merge')mergeIdleActive(state,f.idleId,f.activeId,f.name,f.activeMeaning==='total')
  if(kind==='rates'){for(const key of Object.keys(DEFAULT_RATES))state.rates[key]=num(f[key],'Energy rate',0,10)}
  if(kind==='remove'){
    if(f.targetKind==='device')state.devices=state.devices.filter(x=>x.id!==id)
    if(f.targetKind==='solar')state.solarReadings=state.solarReadings.filter(x=>x.id!==id)
    if(f.targetKind==='bill')state.bills=state.bills.filter(x=>x.id!==id)
    if(f.targetKind==='device-log')state.devices.find(x=>x.id===id).logs=state.devices.find(x=>x.id===id).logs.filter(x=>x.id!==f.logId)
  }
  validateState(state);save();$('#modal').close();render();toast(kind==='remove'?'Record removed.':'Saved to this browser.')
}catch(error){state=oldState;$('#form-error').textContent=error.message}})
document.addEventListener('change',e=>{
  if(e.target.matches('#active-form [name=daysMode],#active-form [name=runMode],#active-form [name=nightTime],#active-form [name=inputMode]'))syncForm()
  if(e.target.id==='all-week'){
    document.querySelectorAll('#active-form input[name="days"]').forEach(day=>{day.checked=e.target.checked})
    return
  }
  if(e.target.matches('#active-form input[name="days"]')){
    const all=$('#all-week');if(all)all.checked=[...document.querySelectorAll('#active-form input[name="days"]')].every(day=>day.checked)
    return
  }
  if(e.target.id==='period-select'){selectPeriod(e.target.value);render()}})
document.addEventListener('input',e=>{if(e.target.id==='device-search'){filter=e.target.value;const selection=e.target.selectionStart;render();$('#device-search').focus();$('#device-search').setSelectionRange(selection,selection)}})
$('#export-side').addEventListener('click',exportBackup)
$('#import-side').addEventListener('click',()=>$('#backup-file').click())
$('#export-footer').addEventListener('click',exportBackup)
$('#import-footer').addEventListener('click',()=>$('#backup-file').click())
$('#about-button').addEventListener('click',explain)
$('#backup-file').addEventListener('change',async e=>{if(READ_ONLY)return;const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>5000000)throw new Error('Backup must be smaller than 5 MB.');const incoming=validateState(JSON.parse(await file.text()));modal('Restore this backup?','This replaces the data currently saved in this browser.',`<div class="notice">${incoming.devices.length} devices · ${incoming.bills.length} bills · ${incoming.solarReadings.length} solar readings.<br>Export your current data before replacing it.</div><button type="button" class="text-button" id="backup-before-restore">Export current data first</button>`,'Restore backup','restore');$('#backup-before-restore').onclick=exportBackup;const form=$('#active-form');form.addEventListener('submit',event=>{event.preventDefault();event.stopImmediatePropagation();state=incoming;loadWarning='';save();selectPeriod('current');$('#modal').close();render();toast('Backup restored.')})}catch(error){toast(error.message)}})
if(READ_ONLY){document.body.classList.add('read-only');for(const id of ['export-side','import-side','export-footer','import-footer','backup-file'])$('#'+id)?.remove();$('.local-note').innerHTML='<div>Published snapshot<small>Updates are made in the local app.</small></div>'}
window.addEventListener('hashchange',()=>{filter='';render()})
render()
